css:
.bfin-sim-container {
    padding: 24px;
    background: #0a0f1e;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e0e6f0;
}
.bfin-sim-header {
    border-left: 4px solid #00bfff;
    padding: 22px 28px;
    margin-bottom: 22px;
    background: rgba(0,191,255,0.06);
    border-radius: 0 8px 8px 0;
}
.bfin-sim-tag {
    color: #70829a;
    font-size: 0.7rem;
    letter-spacing: 0.18em;
    margin-bottom: 8px;
    font-weight: 600;
}
.bfin-sim-header h1 {
    color: #e8f1ff;
    font-size: 1.55rem;
    letter-spacing: 0.02em;
    margin: 0 0 6px 0;
    font-weight: 600;
}
.bfin-sim-subtag {
    color: #8aa0bd;
    font-size: 0.92rem;
    letter-spacing: 0.01em;
}
.bfin-sim-period-bar {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 14px 20px;
    margin-bottom: 22px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 12px;
}
.bfin-sim-rlabel, .bfin-sim-rof {
    color: #70829a;
    font-size: 0.8rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    margin-right: 8px;
}
.bfin-sim-rnum, .bfin-sim-rmax {
    color: #00bfff;
    font-size: 1.1rem;
    font-weight: 700;
    margin-right: 8px;
}
.bfin-sim-round-name {
    color: #e8f1ff;
    font-size: 0.95rem;
    font-weight: 500;
    letter-spacing: 0.01em;
}
.bfin-sim-status-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
    gap: 14px;
    margin-bottom: 22px;
}
.bfin-sim-status-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 18px 18px 16px 18px;
    position: relative;
    overflow: hidden;
}
.bfin-sim-status-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: linear-gradient(90deg, #00bfff, #1e88e5);
}
.bfin-sim-card-ic::before {
    background: linear-gradient(90deg, #00ff88, #00d97a);
}
.bfin-sim-label {
    color: #70829a;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin-bottom: 6px;
    font-weight: 600;
}
.bfin-sim-value {
    font-size: 1.85rem;
    font-weight: 700;
    color: #00bfff;
    line-height: 1.1;
    margin-bottom: 4px;
    letter-spacing: -0.01em;
}
.bfin-sim-card-ic .bfin-sim-value {
    color: #00ff88;
}
.bfin-sim-sublabel {
    color: #70829a;
    font-size: 0.72rem;
    letter-spacing: 0.04em;
}
.bfin-sim-briefing-panel {
    background: #0d1424;
    border: 1px solid #1f2d3d;
    border-left: 3px solid #ff9f43;
    border-radius: 6px;
    padding: 18px 22px;
    margin-bottom: 22px;
}
.bfin-sim-briefing-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 10px;
}
.bfin-sim-briefing-tag {
    color: #ff9f43;
    font-size: 0.7rem;
    letter-spacing: 0.18em;
    font-weight: 700;
}
.bfin-sim-briefing-clock {
    color: #70829a;
    font-size: 0.85rem;
    font-weight: 600;
    letter-spacing: 0.06em;
}
.bfin-sim-briefing-body {
    color: #c8d3e3;
    font-size: 0.93rem;
    line-height: 1.55;
}
.bfin-sim-briefing-body em {
    color: #ffd699;
    font-style: italic;
}
.bfin-sim-briefing-body strong {
    color: #e8f1ff;
}
.bfin-sim-controls {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 22px 24px;
    margin-bottom: 22px;
}
.bfin-sim-controls h3 {
    color: #00bfff;
    font-size: 1rem;
    letter-spacing: 0.04em;
    margin: 0 0 18px 0;
    font-weight: 600;
    text-transform: uppercase;
}
.bfin-sim-decision-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: 18px;
}
.bfin-sim-decision-block label {
    display: block;
    color: #8aa0bd;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 6px;
    font-weight: 600;
}
.bfin-sim-controls input[type="number"],
.bfin-sim-controls select {
    background: #0a0f1e;
    border: 1px solid #2d3f55;
    color: #e0e6f0;
    border-radius: 4px;
    padding: 9px 12px;
    width: 100%;
    font-size: 0.92rem;
    font-family: inherit;
    transition: border-color 0.2s ease;
}
.bfin-sim-controls input[type="number"]:focus,
.bfin-sim-controls select:focus {
    outline: none;
    border-color: #00bfff;
    box-shadow: 0 0 0 2px rgba(0,191,255,0.2);
}
.bfin-sim-controls select option {
    background: #111827;
    color: #e0e6f0;
}
.bfin-sim-helper {
    color: #70829a;
    font-size: 0.74rem;
    margin-top: 6px;
    letter-spacing: 0.02em;
}
.bfin-sim-weight-warning {
    color: #ff6b35;
    font-size: 0.85rem;
    margin-top: 14px;
    padding: 10px 14px;
    background: rgba(255,107,53,0.08);
    border: 1px solid rgba(255,107,53,0.3);
    border-radius: 4px;
    display: none;
}
.bfin-sim-weight-warning.bfin-sim-show {
    display: block;
}
.bfin-sim-action-bar {
    display: flex;
    gap: 12px;
    margin-bottom: 26px;
    flex-wrap: wrap;
}
.bfin-sim-action-bar .btn-primary {
    background: linear-gradient(135deg, #00bfff, #0080cc);
    border: none;
    color: #fff;
    padding: 12px 28px;
    font-size: 0.92rem;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    border-radius: 4px;
    box-shadow: 0 0 12px rgba(0,191,255,0.25);
    transition: all 0.2s ease;
}
.bfin-sim-action-bar .btn-primary:hover {
    box-shadow: 0 0 18px rgba(0,191,255,0.5);
    transform: translateY(-1px);
}
.bfin-sim-action-bar .btn-outline-secondary {
    background: transparent;
    border: 1px solid #2d3f55;
    color: #8aa0bd;
    padding: 10px 20px;
    font-size: 0.85rem;
    border-radius: 4px;
    letter-spacing: 0.04em;
}
.bfin-sim-action-bar .btn-outline-secondary:hover {
    background: rgba(45,63,85,0.4);
    color: #e0e6f0;
}
.bfin-sim-history {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px 24px;
    margin-bottom: 22px;
}
.bfin-sim-history h3 {
    color: #00bfff;
    font-size: 0.9rem;
    letter-spacing: 0.06em;
    margin: 0 0 14px 0;
    font-weight: 600;
    text-transform: uppercase;
}
.bfin-sim-history table {
    background: transparent;
    color: #c8d3e3;
    font-size: 0.86rem;
    margin: 0;
}
.bfin-sim-history table thead th {
    color: #70829a;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    border-bottom: 1px solid #2d3f55;
    padding: 10px 8px;
    font-weight: 600;
    background: transparent;
}
.bfin-sim-history table tbody td {
    border-top: 1px solid #1a2536;
    padding: 10px 8px;
    color: #c8d3e3;
}
.bfin-sim-history table tbody tr:hover td {
    background: rgba(0,191,255,0.04);
}
.bfin-sim-chart-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(360px, 1fr));
    gap: 18px;
    margin-bottom: 22px;
}
.bfin-sim-chart-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px 22px;
}
.bfin-sim-chart-card h4 {
    color: #00bfff;
    font-size: 0.85rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin: 0 0 14px 0;
    font-weight: 600;
}
.bfin-sim-chart-wrap {
    height: 240px;
    position: relative;
}
@media (max-width: 768px) {
    .bfin-sim-container {
        padding: 14px;
    }
    .bfin-sim-header {
        padding: 16px 18px;
    }
    .bfin-sim-header h1 {
        font-size: 1.2rem;
    }
    .bfin-sim-status-grid {
        grid-template-columns: 1fr 1fr;
    }
    .bfin-sim-value {
        font-size: 1.4rem;
    }
    .bfin-sim-decision-grid {
        grid-template-columns: 1fr;
    }
    .bfin-sim-chart-grid {
        grid-template-columns: 1fr;
    }
}


/* --- EQIL v1.1.0: focus visibility, reduced motion, completion banner --- */
:is(input, select, button, a):focus-visible {
    outline: 3px solid #7fd4ff;
    outline-offset: 2px;
    border-radius: 3px;
}
@media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important;
        scroll-behavior: auto !important;
    }
}
.bfin-sim-complete {
    margin: 12px 0;
    padding: 12px 14px;
    border: 1px solid #3ddc97;
    border-radius: 4px;
    background: rgba(61, 220, 151, 0.08);
    color: #bff5d8;
    font-weight: 600;
}

