                    return window.mySimulation.t('hint_low_credibility');
                }
            }
            if (round === 3) {
                if (results && results.portfolioSharpe && results.portfolioSharpe < 0.9) {
                    return window.mySimulation.t('hint_low_sharpe');
                }
            }
            if (round === 4) {
                if (state.domainState.icScore < 100) {
                    return window.mySimulation.t('hint_ic_low');
                }
            }
            return null;
        }

