        getPresets() { return null; }

        // Single place that turns the run into the 0-100 figure the reporting layer
        // reads, so composite, overallScore, totalScore and score cannot drift.
        // IC score is the primary axis (max 180 across the three rounds), with the
        // structural reframe and the disciplined allocation as the two judgement gates.
        _composite(finalIc, structural, finalAlloc) {
            var base = Math.max(0, Math.min(1, finalIc / 180)) * 80;
            if (structural) base += 12;
            if (finalAlloc === 120) base += 8;
            return Math.max(0, Math.min(100, Math.round(base)));
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var self = this;
            var finalIc = 0, finalSharpe = 0, finalAlloc = 0, structural = false;
            for (var i = 0; i < history.length; i++) {
                var r = history[i].results || {};
                if (r.icScore != null) finalIc = r.icScore;
                if (r.portfolioSharpe) finalSharpe = r.portfolioSharpe;
                if (r.allocation) finalAlloc = r.allocation;
                if (r.structuralReframe) structural = true;
            }
            var overall = this._composite(finalIc, structural, finalAlloc);

            var performance = 'beginner';
            if (finalIc >= 160 && structural && finalAlloc === 120) performance = 'excellent';
            else if (finalIc >= 120 && structural) performance = 'good';
            else if (finalIc >= 80) performance = 'developing';

            var insights = [];
            insights.push(structural ? self._t('insight_structural_ok') : self._t('insight_structural_miss'));
            if (finalAlloc === 120) insights.push(self._t('insight_alloc_ok'));
            else if (finalAlloc === 240) insights.push(self._t('insight_alloc_full'));
            else if (finalAlloc === 60) insights.push(self._t('insight_alloc_timid'));
            if (finalSharpe >= 1.4) insights.push(self._t('insight_sharpe_strong'));
            else if (finalSharpe < 1.0) insights.push(self._t('insight_sharpe_weak'));

            return {
                composite: overall,
                overallScore: overall,
                totalScore: overall,
                score: overall,
                finalIc: finalIc,
                maxIc: 180,
                finalSharpe: Number(finalSharpe.toFixed(2)),
                finalAlloc: finalAlloc,
                structuralReframe: structural,
                performance: performance,
                performanceKey: performance,
                performanceLabel: self._t('perf_' + performance),
                insights: insights
            };
        }

        // Without this the debrief above is computed and then discarded.
        formatCompletionMessage(history) {
            var s = this.getPerformanceSummary(history);
            if (!s || !s.insights) return '';
            var lines = [];
            lines.push(this._t('done_heading'));
            lines.push(this._t('done_score') + ' ' + s.overallScore + '/100 (' + s.performanceLabel + ')');
            lines.push(this._t('done_ic') + ' ' + s.finalIc + '/' + s.maxIc);
            lines.push(this._t('done_sharpe') + ' ' + s.finalSharpe);
            lines.push(this._t('done_alloc') + ' USD ' + s.finalAlloc + 'M');
            s.insights.forEach(function(i) { if (i) lines.push('- ' + i); });
            return lines.join('\n');
        }

        _updateBriefing(state) {
            var round = state.currentPeriod || 1;
            var briefEl = document.getElementById('briefingText');
            var roundNameEl = document.getElementById('roundName');
            var clockEl = document.getElementById('briefingClock');
            var r1 = document.getElementById('round1Controls');
            var r2 = document.getElementById('round2Controls');
            var r3 = document.getElementById('round3Controls');

            var finished = round > 3;
            if (r1) r1.style.display = (!finished && round === 1) ? 'block' : 'none';
            if (r2) r2.style.display = (!finished && round === 2) ? 'block' : 'none';
            if (r3) r3.style.display = (!finished && round === 3) ? 'block' : 'none';

            // Without this the run ends on a live but inert form.
            var row = document.getElementById('actionsRow');
            if (row) row.style.display = finished ? 'none' : '';
            var btn = document.getElementById('nextPeriodBtn');
            if (btn) { btn.disabled = !!finished; btn.style.display = finished ? 'none' : ''; }
            var banner = document.getElementById('runCompleteBanner');
            if (banner) banner.style.display = finished ? '' : 'none';

            if (!window.mySimulation || !window.mySimulation.t) return;

            var briefKey, nameKey, clockText;
            if (round <= 1) {
                briefKey = 'brief_round1';
                nameKey = 'round1_name';
                clockText = '14:30';
            } else if (round === 2) {
                briefKey = 'brief_round2';
                nameKey = 'round2_name';
                clockText = '14:58';
            } else if (round === 3) {
                briefKey = 'brief_round3';
                nameKey = 'round3_name';
                clockText = '15:30';
            } else {
                briefKey = 'brief_complete';
                nameKey = 'round_complete';
                clockText = '16:00';
            }

            if (briefEl) briefEl.innerHTML = window.mySimulation.t(briefKey);
            if (roundNameEl) {
                roundNameEl.setAttribute('data-i18n', nameKey);
                roundNameEl.textContent = window.mySimulation.t(nameKey);
            }
            if (clockEl) clockEl.textContent = clockText;
        }

